using UnityEngine;
using Dreamscape.Characters;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Globalization;
public class ProductionCapture:MonoBehaviour {
 public DreamscapeCampaign game;public bool saveFrames=true; public bool skipOpening;public bool onlyPhase5;Camera cam;CharacterMotor motor;RenderTexture rt;Texture2D tex;int frame;string folder;bool cinematic;Vector3 look;List<string> events=new List<string>();string shot="opening";int failures;float oldScale;
 public static ProductionCapture Active;void Awake(){Active=this;}public static void Emit(string e){if(Active)Active.Mark(e);}
 public void Mark(string e){events.Add(frame+","+(frame/24f).ToString("F3",CultureInfo.InvariantCulture)+","+shot+",\""+e.Replace("\"","\"\"")+"\"");Debug.Log("PRODUCTION "+shot+" "+e);}
 IEnumerator Start(){Application.runInBackground=true;game=FindAnyObjectByType<DreamscapeCampaign>();motor=game.player;cam=game.view;game.enabled=false;motor.GetComponent<PlayerInputController>().enabled=false;cam.GetComponent<Dreamscape.CameraSystem.FirstPersonCamera>().enabled=false;Time.captureFramerate=24;Time.fixedDeltaTime=1f/60;QualitySettings.vSyncCount=0;folder=Path.GetFullPath(Path.Combine(Application.dataPath,"../../work/final-production/frames"));Directory.CreateDirectory(folder);rt=new RenderTexture(1280,720,24);tex=new Texture2D(1280,720,TextureFormat.RGB24,false);cam.targetTexture=rt;motor.Jumped+=()=>Mark("jump");motor.Landed+=()=>Mark("land");yield return null;
 if(!onlyPhase5){foreach(var l in FindObjectsByType<Light>())if(l.type!=LightType.Directional)l.enabled=Mathf.Abs(l.transform.position.x+40)<15;cinematic=true;var actor=GameObject.Find("Carlinhos opening");var walk=actor.GetComponent<TrailerWalkAnimation>();walk.gait=1;Mark("shot_start");
 for(float t=0;t<2.7f;t+=Time.deltaTime){actor.transform.position=new Vector3(-40,0,3+t*1.25f);cam.transform.position=actor.transform.position+new Vector3(-1.3f,1.45f,2.8f);cam.transform.LookAt(actor.transform.position+Vector3.up*1.2f);yield return null;}walk.gait=0;walk.ponder=true;for(float t=0;t<1.3f;t+=Time.deltaTime){cam.transform.position=actor.transform.position+new Vector3(-.7f,1.45f,1.6f-t*.2f);cam.transform.LookAt(actor.transform.position+Vector3.up*1.4f);yield return null;}
 walk.ponder=false;walk.gait=1;for(float t=0;t<1.8f;t+=Time.deltaTime){actor.transform.position=Vector3.Lerp(new Vector3(-40,0,6.375f),new Vector3(-40,0,9.1f),t/1.8f);cam.transform.position=actor.transform.position+new Vector3(1.3f,1.5f,2.3f);cam.transform.LookAt(actor.transform.position+Vector3.up*1.1f);yield return null;}shot="sleep";Mark("shot_start");walk.gait=0;walk.seated=true;var book=CinematicBook.Create(actor.transform);for(float t=0;t<1.7f;t+=Time.deltaTime){actor.transform.position=new Vector3(-40,-.37f*Mathf.SmoothStep(0,1,t/.7f),9.1f);walk.sleep=Mathf.Clamp01((t-.6f)/1.1f);cam.transform.position=new Vector3(-41.2f,1.1f,10.7f);cam.transform.LookAt(actor.transform.position+Vector3.up*1.05f);yield return null;}Mark("dream_transition");
 cinematic=false;var hands=cam.transform.Find("First person sleeves and hands");if(hands)hands.gameObject.SetActive(true);
 shot="phase1_failure";game.Enter(0);Mark("shot_start");yield return Move(new Vector3(-2,0,3),true,3);Mark("power_actual="+motor.HasDoubleJump);yield return Move(new Vector3(0,0,5),true,2);yield return Move(new Vector3(0,0,8),true,1.5f);yield return Wait(.9f);Mark("death");
 shot="phase1";game.Enter(0);Mark("shot_start");yield return Move(new Vector3(-2,0,3),true,3);Mark("power_actual="+motor.HasDoubleJump);yield return Move(new Vector3(-3,0,4),true,2);yield return Leap(new Vector3(-3,0,6),false);yield return Leap(new Vector3(-3,.5f,10),true);yield return Leap(new Vector3(-3,1,14),true);yield return Leap(new Vector3(-3,1.5f,18),true);yield return Leap(new Vector3(-2,1.5f,21),true);yield return Move(new Vector3(0,0,23.3f),false,4);yield return Wait(.5f);yield return Move(new Vector3(0,0,25.3f),true,3);CheckExit(0);
 shot="phase2";game.Enter(1);Mark("shot_start");yield return Move(new Vector3(38,0,3),true,3);Mark("speed");yield return Move(new Vector3(37,0,7.7f),true,3);motor.SetCrouch(true);Mark("crouch");yield return Move(new Vector3(37,0,11.7f),true,5);motor.SetCrouch(false);yield return Wait(.25f);yield return Move(new Vector3(37,0,21.5f),true,4);yield return Move(new Vector3(40,0,23),true,3);yield return Move(new Vector3(40,0,25.3f),true,3);CheckExit(1);
 shot="phase3";game.Enter(2);Mark("shot_start");yield return Move(new Vector3(78,0,3),true,3);Mark("power_actual="+motor.HasDoubleJump);yield return Move(new Vector3(83,0,11),true,4);yield return Leap(new Vector3(83,1.5f,13),true);yield return Interact(new Vector3(83,2.4f,13.7f));yield return Move(new Vector3(80,0,20),true,5);yield return Move(new Vector3(80,0,25.3f),true,4);CheckExit(2);
 shot="phase4";game.Enter(3);Mark("shot_start");yield return Move(new Vector3(120,0,5.1f),true,3);yield return Interact(new Vector3(120,.9f,6.7f));yield return Move(new Vector3(122,0,8.8f),true,3);yield return Move(new Vector3(120,0,14),true,3);yield return Move(new Vector3(120,0,17.3f),true,3);CheckExit(3);
 }cinematic=false;shot="phase5";game.Enter(4);Mark("shot_start");yield return Move(new Vector3(158,0,3),true,3);Mark("speed");yield return Move(new Vector3(160,0,5.4f),true,2);yield return Move(new Vector3(157,0,6),true,2);Mark("safe_pause_pos="+motor.transform.position);yield return Wait(.4f);yield return Move(new Vector3(158.4f,0,6),true,2);yield return Move(new Vector3(160,0,8.7f),true,2);yield return Move(new Vector3(160,0,10),true,2);yield return Move(new Vector3(157,0,10),true,2);yield return Wait(.35f);yield return Move(new Vector3(158.4f,0,10),true,2);yield return Move(new Vector3(160,0,12.7f),true,2);yield return Move(new Vector3(160,0,14),true,2);yield return Move(new Vector3(157,0,14),true,2);yield return Wait(.35f);yield return Move(new Vector3(158.4f,0,14),true,2);yield return Move(new Vector3(160,0,16.7f),true,2);yield return Move(new Vector3(160,0,21.5f),true,3);yield return Move(new Vector3(160,0,25.3f),true,3);CheckExit(4);yield return Wait(.5f);
 Mark("finished_failures="+failures);File.WriteAllLines(Path.Combine(folder,"events.csv"),events);File.WriteAllText(Path.Combine(folder,"complete.txt"),"frames="+frame+" failures="+failures);cam.targetTexture=null;Time.captureFramerate=0;
 #if UNITY_EDITOR
 UnityEditor.EditorApplication.isPlaying=false;
 #endif
 }
 void CheckExit(int expected){float distance=Vector3.Distance(motor.transform.position,game.exits[expected]);bool ok=distance<1.5f;Mark("exit_"+(ok?"PASS":"FAIL")+"_distance="+distance.ToString("F2",CultureInfo.InvariantCulture)+"_pos="+motor.transform.position);if(!ok)failures++;}
 IEnumerator Wait(float seconds){motor.SetMoveInput(Vector3.zero);for(float t=0;t<seconds;t+=Time.deltaTime)yield return null;}
 IEnumerator Move(Vector3 target,bool run,float timeout){motor.SetSprint(run);for(float t=0;t<timeout;t+=Time.deltaTime){var d=target-motor.transform.position;d.y=0;look=target+Vector3.up*1.35f;if(d.magnitude<.16f)break;motor.SetMoveInput(d.normalized*Mathf.Clamp01(d.magnitude/1.1f));yield return null;}motor.SetMoveInput(Vector3.zero);var delta=target-motor.transform.position;delta.y=0;if(delta.magnitude>.4f)Mark("move_BLOCKED_target="+target+"_pos="+motor.transform.position);}
 IEnumerator Leap(Vector3 target,bool second){Mark("leap_start");motor.SetSprint(true);motor.RequestJump();for(float t=0;t<1.8f;t+=Time.deltaTime){Vector3 d=target-motor.transform.position;d.y=0;look=target+Vector3.up*.5f;motor.SetMoveInput(d.magnitude>.12f?d.normalized:Vector3.zero);if(second&&t>=.28f&&t<.28f+Time.deltaTime)motor.RequestJump();yield return null;if(t>.4f&&motor.IsGrounded)break;}motor.SetMoveInput(Vector3.zero);yield return Move(target,true,1.2f);bool ok=Vector3.Distance(new Vector3(target.x,0,target.z),new Vector3(motor.transform.position.x,0,motor.transform.position.z))<.7f&&motor.transform.position.y>=target.y-.2f;Mark("leap_"+(ok?"PASS":"FAIL")+"_y="+motor.transform.position.y.ToString("F2",CultureInfo.InvariantCulture));if(!ok)failures++;yield return Wait(.12f);}
 IEnumerator Interact(Vector3 target){look=target;yield return Wait(.5f);RaycastHit hit;bool ok=Physics.Raycast(cam.transform.position,(target-cam.transform.position).normalized,out hit,2.8f);var m=ok?hit.collider.GetComponentInParent<ProductionMechanism>():null;if(m&&m.kind==2){m.Activate();Mark("button");}else{Mark("button_FAIL_hit="+(ok?hit.collider.name:"none")+"_pos="+motor.transform.position);failures++;}yield return Wait(1.4f);}
 void LateUpdate(){if(!cam||!rt)return;if(!cinematic){var cc=motor.GetComponent<CharacterController>();cam.transform.position=motor.transform.position+cc.center+Vector3.up*(cc.height*.5f-.12f);var q=Quaternion.LookRotation((look-cam.transform.position).normalized);cam.transform.rotation=Quaternion.Slerp(cam.transform.rotation,q,Time.deltaTime*10);}
 if(saveFrames){cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1280,720),0,0);tex.Apply();File.WriteAllBytes(Path.Combine(folder,frame.ToString("D5")+".jpg"),tex.EncodeToJPG(94));RenderTexture.active=null;}frame++;}
}
